def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        print("Error: division by zero")
        return None
    else:
        print(f"Success: {a}/{b} = {result}")
        return result
    finally:
        print("Calculation attempt finished")

answer = safe_divide(10, 3)
print(f"Answer: {answer}")
